import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.SpawnParticleEffect{Dimension: 2, EntityUniqueID: -1, Position: mgl32.Vec3{1, 2, 3},
# ParticleName: "minecraft:heart_particle", MoLangVariables: protocol.Option([]byte(`{"x":1}`))}
WITH_VARIABLES = bytes.fromhex(
    "02010000803f0000004000004040186d696e6563726166743a68656172745f7061727469636c6501077b2278223a317d"
)

# generated by gophertunnel b8bd735:
# packet.SpawnParticleEffect{Dimension: 200, EntityUniqueID: 12345, ParticleName: "minecraft:heart_particle"}
WITHOUT_VARIABLES = bytes.fromhex(
    "c8f2c001000000000000000000000000186d696e6563726166743a68656172745f7061727469636c6500"
)

# generated by gophertunnel b8bd735:
# packet.SpawnParticleEffect{ParticleName: "minecraft:heart_particle", MoLangVariables: protocol.Option([]byte{})}
EMPTY_VARIABLES = bytes.fromhex("0000000000000000000000000000186d696e6563726166743a68656172745f7061727469636c650100")

GOLDENS = [
    pytest.param(
        v2225.SpawnParticleEffectPacket(
            vanilla_dimension_id=2,
            actor_id=-1,
            pos=v2225.Vec3(x=1.0, y=2.0, z=3.0),
            effect_name="minecraft:heart_particle",
            molang_variables='{"x":1}',
        ),
        WITH_VARIABLES,
        id="with-variables",
    ),
    pytest.param(
        v2225.SpawnParticleEffectPacket(
            vanilla_dimension_id=200,
            actor_id=12345,
            effect_name="minecraft:heart_particle",
        ),
        WITHOUT_VARIABLES,
        id="without-variables",
    ),
    pytest.param(
        v2225.SpawnParticleEffectPacket(effect_name="minecraft:heart_particle", molang_variables=""),
        EMPTY_VARIABLES,
        id="empty-variables",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_spawn_particle_effect_is_packet_118(version):
    assert version.PACKETS[118] is version.SpawnParticleEffectPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_spawn_particle_effect_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_spawn_particle_effect_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_an_empty_molang_variable_map_is_not_an_absent_one():
    assert v2225.SpawnParticleEffectPacket.from_bytes(EMPTY_VARIABLES).molang_variables == ""
    assert v2225.SpawnParticleEffectPacket.from_bytes(WITHOUT_VARIABLES).molang_variables is None
